  source: string; // 'crustdata' or a URL
  quote?: string; // exact text on the source page that supports the value
  asOf?: string;
}

export type Agreement = 'agree' | 'conflict' | 'records-only' | 'field-only' | 'neither';

export interface Resolved {
  key: string;
