      const close = [...allowed.replace(/,/g, '').matchAll(/\d+(?:\.\d+)?/g)].some((x) => {
        const v = parseFloat(x[0]);
        return v === n || (v > 0 && Math.abs(v - n) / v < 0.02) || [1e3, 1e6, 1e9].some((k) => Math.abs(v - n * k) / (n * k) < 0.06);
