1	/**
2	 * Run one job in-process and print what came back.
3	 *
4	 *   node --env-file=../.env scripts/try.ts <service> '<json input>'
5	 *   node --env-file=../.env scripts/try.ts person-check '{"name":"Karri Saarinen","company":"Linear","title":"CEO"}'
6	 *   node --env-file=../.env scripts/try.ts --resume <jobId>      (raise a paused job's budget 2x and carry on)
7	 */
8	import { init, flush, shutdown } from 'neatlogs';
9	import type { ServiceId } from '../src/types.ts';
10	
11	const [service, raw] = process.argv.slice(2);
12	if (!service || !raw) {
13	  console.error("usage: scripts/try.ts <service> '<json input>'");
14	  process.exit(1);
15	}
16	
17	await init({ apiKey: process.env.NEATLOGS_API_KEY, endpoint: 'https://ingest.neatlogs.com', workflowName: 'research-job', tags: ['parallax', 'dev'], registerShutdownHandlers: false });
18	const { createJob, runJob } = await import('../src/runner.ts');
19	
20	const { getJob, saveJob } = await import('../src/store.ts');
21	const job = service === '--resume' ? getJob(raw) : createJob(service as ServiceId, JSON.parse(raw), { tag: 'dev' });
22	if (!job) {
23	  console.error('unknown service, job or empty input');
24	  process.exit(1);
25	}
26	if (service === '--resume' && job.quote) {
27	  job.quote.budgetUsd *= 2;
28	  saveJob(job);
29	}
30	console.log(`${job.id}: quoted $${job.quote?.priceUsd} (est. cost $${job.quote?.estCostUsd}, budget $${job.quote?.budgetUsd})`);
31	const t0 = Date.now();
32	await runJob(job.id);
33	const r = job.result ?? {};
34	console.log(`\nstatus:   ${job.status}${job.error ? ` (${job.error})` : ''} in ${((Date.now() - t0) / 1000).toFixed(0)}s`);
35	console.log(`headline: ${r.headline ?? '-'}`);
36	if (r.verdict) console.log(`verdict:  ${r.verdict}`);
37	console.log(`stats:    ${JSON.stringify(r.stats ?? {})}`);

